110	static void AnalysisAxisForBsh(const Shape &qShape, const Shape &kShape, const Shape &vShape, FaShapeInfo &shapeInfo)
111	{
112	    shapeInfo.inputLayout = InputLayout::BSH;
113	    shapeInfo.l0InputLayoutStr = "BSH";
114	    uint64_t dSize = qShape[2] / shapeInfo.axes.n1;
115	    shapeInfo.axes.d = dSize;
116	    if (dSize == 0) {
117	        return;
118	    }
119	    shapeInfo.axes.b = qShape[0];
120	    shapeInfo.axes.n2 = kShape[2] / dSize;
121	    shapeInfo.axes.s1 = qShape[1];
122	    shapeInfo.axes.s2 = kShape[1];
123	    shapeInfo.axes.dk = kShape[2] / shapeInfo.axes.n2;
124	    shapeInfo.axes.dv = vShape[2] / shapeInfo.axes.n2;
125	}
