180	static aclnnStatus AnalysisAxis(const aclTensor *query,
181	                                const aclTensor *key,
182	                                const aclTensor *value,
183	                                const char *inputLayout,
184	                                int64_t headNum,
185	                                FaShapeInfo &shapeInfo)
186	{
187	    Shape qShape = query->GetViewShape();
188	    Shape kShape = key->GetViewShape();
189	    Shape vShape = value->GetViewShape();
190	    shapeInfo.dimNum = qShape.GetDimNum();
191	
192	    // 记录轴的长度 b, n2, g, s1, s2, d
193	    // H1等于N1*D, H2等于N2*D
194	    // N1等于g*N2
195	    shapeInfo.axes.n1 = headNum;
196	    std::string inputLayoutStr = op::ToString(inputLayout).GetString();
197	    if (shapeInfo.dimNum == DIM_NUM_3 && inputLayoutStr == "BSH") {
198	        // query: (B,S1,N1*D)
199	        // key/value: (B,S2,N2*D)
200	        AnalysisAxisForBsh(qShape, kShape, vShape, shapeInfo);
201	    } else if (shapeInfo.dimNum == DIM_NUM_4 && inputLayoutStr == "BSND") {
202	        // query: (B,S1,N1,D)
203	        // key/value: (B,S2,N2,D)
204	        AnalysisAxisForBsnd(qShape, kShape, vShape, shapeInfo);
205	    } else if (shapeInfo.dimNum == DIM_NUM_3 && inputLayoutStr == "SBH") {
206	        // query: (S1,B,N1*D)
207	        // key/value: (S2,B,N2*D)
208	        AnalysisAxisForSbh(qShape, kShape, vShape, shapeInfo);
209	    } else if (shapeInfo.dimNum == DIM_NUM_4 && inputLayoutStr == "BNSD") {
210	        // query: (B,N1,S1,D)
211	        // key/value: (B,N2,S2,D)
212	        AnalysisAxisForBnsd(qShape, kShape, vShape, shapeInfo);
213	    } else if (shapeInfo.dimNum == DIM_NUM_3 && inputLayoutStr == "TND") {
214	        // query: (T,N1,D)
215	        // key/value: (T,N2,D)
216	        AnalysisAxisForTnd(qShape, kShape, vShape, shapeInfo);
217	    } else {
218	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "not support input_layout %s with dim_num %lu", inputLayout, shapeInfo.dimNum);
219	        return ACLNN_ERR_PARAM_INVALID;
220	    }
221	    if (shapeInfo.axes.d != shapeInfo.axes.dk) {
222	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
223	                "qD and kD should be same, but got qD=%ld kD=%ld",
224	                shapeInfo.axes.d,
225	                shapeInfo.axes.dk);
226	        return ACLNN_ERR_PARAM_INVALID;
227	    }
228	    if (shapeInfo.axes.d < shapeInfo.axes.dv) {
229	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
230	                "only support kD >= vD, but got kD=%ld vD=%ld",
231	                shapeInfo.axes.d,
232	                shapeInfo.axes.dv);
233	        return ACLNN_ERR_PARAM_INVALID;
234	    }
235	    return ACLNN_SUCCESS;
236	}
