238	static void SetShapeInfoForBshBsnd(int64_t alignedH1Size, FaShapeInfo &shapeInfo)
239	{
240	    if (alignedH1Size > MAX_STRIDE_S1) {
241	        shapeInfo.needTranspose = true;
242	        shapeInfo.needReshape = true;
243	        shapeInfo.l0InputLayoutStr = "BNSD";
244	
245	        // B,S,N,D -> B,N,S,D
246	        shapeInfo.perm_in.assign({0, 2, 1, 3});
247	        // B,N,S,D -> B,S,N,D
248	        shapeInfo.perm_out.assign(shapeInfo.perm_in.cbegin(), shapeInfo.perm_in.cend());
249	    }
250	    if (shapeInfo.needPad) {
251	        shapeInfo.needReshape = true;
252	    }
253	
254	    if (shapeInfo.inputLayout == InputLayout::BSND) {
255	        shapeInfo.needReshape = false;
256	    }
257	    if (shapeInfo.needReshape) {
258	        if (!shapeInfo.needTranspose) {
259	            shapeInfo.l0InputLayoutStr = "BSND";
260	        }
261	        shapeInfo.reshapedQueryShape.assign({shapeInfo.axes.b, shapeInfo.axes.s1, shapeInfo.axes.n1, shapeInfo.axes.d});
262	        shapeInfo.reshapedKeyShape.assign({shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.d});
263	        shapeInfo.reshapedValueBefore.assign(
264	            {shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.dv});
265	    }
266	}
267	
268	static void SetShapeInfoForSbh(int64_t alignedH1Size, FaShapeInfo &shapeInfo)
269	{
270	    if (shapeInfo.axes.b * alignedH1Size > MAX_STRIDE_S1) {
271	        shapeInfo.needTranspose = true;
272	        shapeInfo.needReshape = true;
273	        shapeInfo.l0InputLayoutStr = "BNSD";
274	
275	        // S,B,N,D -> B,N,S,D
276	        shapeInfo.perm_in.assign({1, 2, 0, 3});
277	        // B,N,S,D -> S,B,N,D
278	        shapeInfo.perm_out.assign({2, 0, 1, 3});
279	    }
280	    if (shapeInfo.needPad) {
281	        shapeInfo.needReshape = true;
282	    }
283	
284	    if (shapeInfo.needReshape) {
285	        if (!shapeInfo.needTranspose) {
286	            shapeInfo.l0InputLayoutStr = "SBH";
287	        }
288	        shapeInfo.reshapedQueryShape.assign({shapeInfo.axes.s1, shapeInfo.axes.b, shapeInfo.axes.n1, shapeInfo.axes.d});
289	        shapeInfo.reshapedKeyShape.assign({shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.d});
290	        shapeInfo.reshapedValueBefore.assign(
291	            {shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.dv});
292	    }
293	}
