295	static int64_t GetSumIntArrayMaxValue(const aclIntArray *intArrayValue)
296	{
297	    // 获取targetLengthsList中的最大值
298	    int64_t maxLength = 0;
299	    if (intArrayValue->Size() == 1) {
300	        maxLength = static_cast<int64_t>((*intArrayValue)[0]);
301	        return maxLength;
302	    }
303	    maxLength = static_cast<int64_t>((*intArrayValue)[0]);
304	    for (size_t i = 1; i < intArrayValue->Size(); ++i) {
305	        int64_t tmpMaxLength = static_cast<int64_t>((*intArrayValue)[i])
306	                                - static_cast<int64_t>((*intArrayValue)[i - 1]);
307	        if (tmpMaxLength > maxLength) {
308	            maxLength = tmpMaxLength;
309	        }
310	    }
311	    return maxLength;
312	}
