314	static int64_t getSeqLenQSum(const aclIntArray *actualSeqQLenOptional)
315	{
316	    if (actualSeqQLenOptional->Size() < 1) {
317	        return 0;
318	    }
319	    int64_t sQLenSum = 0;
320	    for (int64_t i = actualSeqQLenOptional->Size() - 1; i >= 0; --i) {
321	        sQLenSum = static_cast<int64_t>((*actualSeqQLenOptional)[i]);
322	        if (sQLenSum > 0) {
323	            break;
324	        }
325	    }
326	    return sQLenSum;
327	}
