329	static bool IsNeedPad(FaShapeInfo &shapeInfo,
330	                      const aclIntArray *actualSeqQLenOptional,
331	                      const aclIntArray *actualSeqKvLenOptional)
332	{
333	    if (shapeInfo.inputLayout != InputLayout::BNSD && shapeInfo.inputLayout != InputLayout::TND &&
334	        shapeInfo.axes.n1 == shapeInfo.axes.n2 && shapeInfo.needTranspose == false) {
335	        if (shapeInfo.axes.d == HEAD_DIM_72 || shapeInfo.axes.d == HEAD_DIM_88) {
336	            shapeInfo.padNum = 0;
337	        }
338	        if (shapeInfo.axes.dv == HEAD_DIM_72 || shapeInfo.axes.dv == HEAD_DIM_88) {
339	            shapeInfo.padNumv = 0;
340	        }
341	        if ((shapeInfo.axes.d == HEAD_DIM_72 || shapeInfo.axes.d == HEAD_DIM_88) &&
342	            (shapeInfo.axes.dv == HEAD_DIM_72 || shapeInfo.axes.dv == HEAD_DIM_88)) {
343	            return false;
344	        }
345	        return true;
346	    }
347	
348	    if (shapeInfo.inputLayout == InputLayout::TND) {
349	        if (shapeInfo.axes.d >= TND_UNPAD_MAX_DDIM) {
350	            return true;
351	        }
352	        int64_t sKvLenMax = 0;
353	        int64_t sQLenSum = 0;
354	        if (actualSeqQLenOptional != nullptr && actualSeqKvLenOptional != nullptr &&
355	            actualSeqQLenOptional->Size() == actualSeqKvLenOptional->Size()) {
356	            sKvLenMax = GetSumIntArrayMaxValue(actualSeqKvLenOptional);
357	            sQLenSum = getSeqLenQSum(actualSeqQLenOptional);
358	        }
359	
360	        if (sKvLenMax == 0 || sQLenSum == 0) {
361	            // 走原来逻辑是否pad
362	            OP_LOGD("Fa aclnn TND case sKvLenMax(%ld) or sQLenSum(%ld) is 0.", sKvLenMax, sQLenSum);
363	            return true;
364	        }
365	
366	        if ((sKvLenMax <= TND_UNPAD_MAX_S2) && (sQLenSum < TND_UNPAD_MAX_S1_SUM)) {
367	            // 去除pad
368	            OP_LOGD("Fa aclnn TND case do not do pad dimD operation.");
369	            shapeInfo.padNum = 0;
370	            shapeInfo.padNumv = 0;
371	            return false;
372	        }
373	    }
374	    return true;
375	}
