377	static bool IsCapableSameAB(const FaShapeInfo &shapeInfo, const aclTensor *query)
378	{
379	    if (query->GetDataType() == op::DataType::DT_FLOAT) {
380	        return false;
381	    }
382	    if (((shapeInfo.axes.d + shapeInfo.padNum) % FRACTAL_NUM != 0 || shapeInfo.axes.d == D_SPECIFIC_SIZE_96) &&
383	        (shapeInfo.axes.s2 >= S2_REUSE_SIZE_512)) {
384	        return true;
385	    }
386	    if (shapeInfo.axes.s2 > s2sizeLimitMin && shapeInfo.axes.d > SAMEAB_D_LIMIT_128 &&
387	        shapeInfo.axes.d < SAMEAB_D_LIMIT_196) {
388	        return true;
389	    }
390	    return false;
391	}
