393	static bool isSupportMLA(const FaShapeInfo &shapeInfo, const aclTensor *query)
394	{
395	    // TND模板支持MLA
396	    if (shapeInfo.inputLayout == InputLayout::TND) {
397	        return true;
398	    }
399	    // SameAB模板支持MLA
400	    if (IsCapableSameAB(shapeInfo, query)) {
401	        return true;
402	    }
403	    // S1S2模板支持MLA
404	    if (shapeInfo.axes.s2 > s2sizeLimitMin) {
405	        return true;
406	    }
407	    return false;
408	}
