410	static aclnnStatus InputDtypeCheck(const aclTensor *query,
411	                                   const aclTensor *key,
412	                                   const aclTensor *value,
413	                                   const aclTensor *attentionOut,
414	                                   const aclTensor *realShiftOptional,
415	                                   int64_t pseType,
416	                                   const aclTensor *sinkOptional)
417	{
418	    auto vDtype = value->GetDataType();
419	    auto kDtype = key->GetDataType();
420	    auto qDtype = query->GetDataType();
421	    auto outDtype = attentionOut->GetDataType();
422	    if (qDtype != kDtype || kDtype != vDtype) {
423	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
424	                "The data type of query[%s], key[%s], value[%s] are not equal.",
425	                op::ToString(DataType(qDtype)).GetString(),
426	                op::ToString(DataType(kDtype)).GetString(),
427	                op::ToString(DataType(vDtype)).GetString());
428	        return ACLNN_ERR_PARAM_INVALID;
429	    }
430	
431	    if (StrideLimited() &&
432	        !(qDtype == op::DataType::DT_FLOAT || qDtype == op::DataType::DT_FLOAT16 || qDtype == op::DataType::DT_BF16)) {
433	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
434	                "The data type of query/key/value is [%s], should be fp16, bf16 or fp32.",
435	                op::ToString(DataType(qDtype)).GetString());
436	        return ACLNN_ERR_PARAM_INVALID;
437	    }
438	    if (pseType == PSE_INNER_MUL_ADD || pseType == PSE_INNER_MUL_ADD_SQRT) {
439	        // Inner pse alibi, dtype must be fp32
440	        if (realShiftOptional == nullptr) {
441	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "When pseType is 2 or 3, pseShape cannot be null.");
442	            return ACLNN_ERR_PARAM_INVALID;
443	        }
444	        auto pseDtype = realShiftOptional->GetDataType();
445	        if (pseDtype != op::DataType::DT_FLOAT) {
446	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
447	                    "The data type %s of pse is not invalid in pse type 2 or 3 mode, It must be float32",
448	                    op::ToString(DataType(pseDtype)).GetString());
449	            return ACLNN_ERR_PARAM_INVALID;
450	        }
451	        return ACLNN_SUCCESS;
452	    }
453	    if (realShiftOptional != nullptr) {
454	        auto pseDtype = realShiftOptional->GetDataType();
455	        if (pseDtype != outDtype) {
456	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
457	                    "The data type %s of pse is not equal to the data type %s of attentionOut.",
458	                    op::ToString(DataType(pseDtype)).GetString(),
459	                    op::ToString(DataType(outDtype)).GetString());
460	            return ACLNN_ERR_PARAM_INVALID;
461	        }
462	    }
463	    if (sinkOptional != nullptr) {
464	        auto sinkDtype = sinkOptional->GetDataType();
465	        if (sinkDtype != op::DataType::DT_FLOAT) {
466	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
467	                    "The data type of sink is [%s], should be fp32.",
468	                    op::ToString(DataType(sinkDtype)).GetString());
469	            return ACLNN_ERR_PARAM_INVALID;
470	        }
471	    }
472	    return ACLNN_SUCCESS;
473	}
