475	static inline bool CheckFormat(const aclTensor *query,
476	                               const aclTensor *queryRope,
477	                               const aclTensor *key,
478	                               const aclTensor *keyRope,
479	                               const aclTensor *value,
480	                               const aclTensor *realShiftOptional,
481	                               const aclTensor *dropMaskOptional,
482	                               const aclTensor *paddingMaskOptional,
483	                               const aclTensor *attenMaskOptional,
484	                               const aclTensor *sinkOptional,
485	                               const aclTensor *softmaxMaxOut,
486	                               const aclTensor *softmaxSumOut,
487	                               const aclTensor *attentionOutOut)
488	{
489	    bool formatValid = query->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
490	                       key->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
491	                       value->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
492	                       softmaxMaxOut->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
493	                       softmaxSumOut->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
494	                       attentionOutOut->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ;
495	    if (!formatValid) {
496	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
497	                "Input and output format do not support [NZ]. Actual: query:[%s], key:[%s], value:[%s], "
498	                "softmaxMaxOut:[%s], softmaxSumOut:[%s], attentionOutOut:[%s].",
499	                op::ToString(query->GetStorageFormat()).GetString(),
500	                op::ToString(key->GetStorageFormat()).GetString(),
501	                op::ToString(value->GetStorageFormat()).GetString(),
502	                op::ToString(softmaxMaxOut->GetStorageFormat()).GetString(),
503	                op::ToString(softmaxSumOut->GetStorageFormat()).GetString(),
504	                op::ToString(attentionOutOut->GetStorageFormat()).GetString());
505	        return false;
506	    }
507	    if (queryRope != nullptr) {
508	        formatValid = (formatValid && queryRope->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
509	    }
510	    if (keyRope != nullptr) {
511	        formatValid = (formatValid && keyRope->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
512	    }
513	    if (realShiftOptional != nullptr) {
514	        formatValid = (formatValid && realShiftOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
515	    }
516	    if (dropMaskOptional != nullptr) {
517	        formatValid = (formatValid && dropMaskOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
518	    }
519	    if (paddingMaskOptional != nullptr) {
520	        formatValid = (formatValid && paddingMaskOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
521	    }
522	    if (attenMaskOptional != nullptr) {
523	        formatValid = (formatValid && attenMaskOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
524	    }
525	    if (sinkOptional != nullptr) {
526	        formatValid = (formatValid && sinkOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
527	    }
528	    if (!formatValid) {
529	        OP_LOGE(
530	            ACLNN_ERR_PARAM_INVALID,
531	            "Optional input format do not support [NZ]. Actual: queryRope:[%s], keyRope:[%s], realShiftOptional:[%s], "
532	            "dropMaskOptional:[%s], paddingMaskOptional:[%s], attenMaskOptional:[%s], sinkOptional:[%s].",
533	            op::ToString(queryRope->GetStorageFormat()).GetString(),
534	            op::ToString(keyRope->GetStorageFormat()).GetString(),
535	            op::ToString(realShiftOptional->GetStorageFormat()).GetString(),
536	            op::ToString(dropMaskOptional->GetStorageFormat()).GetString(),
537	            op::ToString(paddingMaskOptional->GetStorageFormat()).GetString(),
538	            op::ToString(attenMaskOptional->GetStorageFormat()).GetString(),
539	            op::ToString(sinkOptional->GetStorageFormat()).GetString());
540	        return false;
541	    }
542	    return formatValid;
543	}
