545	static aclnnStatus AnalysisInput(const aclTensor *query,
546	                                 const aclTensor *key,
547	                                 const aclTensor *value,
548	                                 char *inputLayout,
549	                                 int64_t headNum,
550	                                 FaShapeInfo &shapeInfo,
551	                                 const aclIntArray *actualSeqQLenOptional = nullptr,
552	                                 const aclIntArray *actualSeqKvLenOptional = nullptr)
553	{
554	    if (headNum <= 0) {
555	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "head_num must > 0, but got %ld", headNum);
556	        return ACLNN_ERR_PARAM_INVALID;
557	    }
558	    CHECK_RET(AnalysisAxis(query, key, value, inputLayout, headNum, shapeInfo) == ACLNN_SUCCESS,
559	              ACLNN_ERR_PARAM_INVALID);
560	
561	    if (shapeInfo.axes.d > HEAD_DIM_MAX) {
562	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Head dim must <= 768, but got %ld", shapeInfo.axes.d);
563	        return ACLNN_ERR_PARAM_INVALID;
564	    }
565	
566	    if ((actualSeqQLenOptional != nullptr && actualSeqKvLenOptional != nullptr) &&
567	        (actualSeqQLenOptional->Size() > MAX_VAR_LEN_SEQ_LEN || actualSeqKvLenOptional->Size() > MAX_VAR_LEN_SEQ_LEN)) {
568	        OP_LOGW("The input parameter exceeds the operator range, unknown risks exist: "
569	                "actualSeqQLen size and actualSeqKvLen size must <= 20000, but got %lu.",
570	                actualSeqQLenOptional->Size());
571	    }
572	
573	    if (shapeInfo.axes.n2 == 0 || shapeInfo.axes.d == 0) {
574	        return ACLNN_SUCCESS;
575	    }
576	
577	    if (shapeInfo.inputLayout != InputLayout::TND &&
578	        (shapeInfo.axes.b == 0 || shapeInfo.axes.s1 == 0 || shapeInfo.axes.s2 == 0)) {
579	        return ACLNN_SUCCESS;
580	    }
581	
582	    if (!StrideLimited()) {
583	        return ACLNN_SUCCESS;
584	    }
585	
586	    int64_t alignDim = (shapeInfo.axes.d < PAD_LOWER_BOUND_196 || shapeInfo.axes.d == PAD_ALIGN_SPL_SHAPE)
587	                           ? PAD_BASIC_BLOCK
588	                           : PAD_ALIGN_128;
589	    if (shapeInfo.axes.d % alignDim != 0 || shapeInfo.axes.dv % alignDim != 0) {
590	        shapeInfo.needPad = true;
591	        shapeInfo.padNum = (shapeInfo.axes.d + alignDim - 1) / alignDim * alignDim - shapeInfo.axes.d;
592	        shapeInfo.padNumv = (shapeInfo.axes.dv + alignDim - 1) / alignDim * alignDim - shapeInfo.axes.dv;
593	    }
594	
595	    // 硬件亲和dim适配
596	    if ((shapeInfo.axes.d != shapeInfo.axes.dv) &&
597	        (shapeInfo.axes.d == HEAD_DIM_128 || shapeInfo.axes.d == HEAD_DIM_64 || shapeInfo.axes.d == HEAD_DIM_80)) {
598	        shapeInfo.needPad = true;
599	        shapeInfo.padNumv = shapeInfo.padNum + shapeInfo.axes.d - shapeInfo.axes.dv;
600	    }
601	
602	    int64_t alignedH1Size = shapeInfo.axes.n1 * (shapeInfo.axes.d + shapeInfo.padNum);
603	    if (shapeInfo.inputLayout == InputLayout::BSH || shapeInfo.inputLayout == InputLayout::BSND) {
604	        SetShapeInfoForBshBsnd(alignedH1Size, shapeInfo);
605	    } else if (shapeInfo.inputLayout == InputLayout::SBH) {
606	        SetShapeInfoForSbh(alignedH1Size, shapeInfo);
607	    }
608	
609	    if (!IsNeedPad(shapeInfo, actualSeqQLenOptional, actualSeqKvLenOptional)) {
610	        shapeInfo.needPad = false;
611	        shapeInfo.needReshape = false;
612	        if (shapeInfo.inputLayout == InputLayout::BSH) {
613	            shapeInfo.l0InputLayoutStr = "BSH";
614	        }
615	    }
616	
617	    if ((shapeInfo.axes.d != shapeInfo.axes.dv) && (!isSupportMLA(shapeInfo, query))) {
618	        shapeInfo.needPadValue = true;
619	        shapeInfo.needPad = true;
620	        if (shapeInfo.inputLayout == InputLayout::SBH || shapeInfo.inputLayout == InputLayout::BSH) {
621	            shapeInfo.needReshape = true;
622	        }
623	        if (shapeInfo.inputLayout == InputLayout::BSH && !shapeInfo.needTranspose) {
624	            shapeInfo.l0InputLayoutStr = "BSND";
625	        }
626	        shapeInfo.padNumv = shapeInfo.padNum + shapeInfo.axes.d - shapeInfo.axes.dv;
627	        if (shapeInfo.inputLayout == InputLayout::BSH) {
628	            shapeInfo.reshapedQueryShape.assign(
629	                {shapeInfo.axes.b, shapeInfo.axes.s1, shapeInfo.axes.n1, shapeInfo.axes.d});
630	            shapeInfo.reshapedKeyShape.assign(
631	                {shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.d});
632	            shapeInfo.reshapedValueBefore.assign(
633	                {shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.dv});
634	        }
635	        if (shapeInfo.inputLayout == InputLayout::SBH) {
636	            shapeInfo.reshapedQueryShape.assign(
637	                {shapeInfo.axes.s1, shapeInfo.axes.b, shapeInfo.axes.n1, shapeInfo.axes.d});
638	            shapeInfo.reshapedKeyShape.assign(
639	                {shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.d});
640	            shapeInfo.reshapedValueBefore.assign(
641	                {shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.dv});
642	        }
643	    }
644	
645	    OP_LOGD("Analysis input success. Analysis result: [needReshape]: %d, [needPad]: %d, [padNum]: %lu, [padNumv]: %lu,"
646	            "[needTranspose]: %d, [needPadValue]: %d.",
647	            shapeInfo.needReshape,
648	            shapeInfo.needPad,
649	            shapeInfo.padNum,
650	            shapeInfo.padNumv,
651	            shapeInfo.needTranspose,
652	            shapeInfo.needPadValue);
653	    return ACLNN_SUCCESS;
654	}
