656	static inline const aclTensor *GeneratePaddings(int32_t dimNum, int32_t padNum, aclOpExecutor *executor)
657	{
658	    // 2代表每根轴的前后都可以补0
659	    FVector<int64_t> padVec(dimNum * 2, 0);
660	    padVec[padVec.size() - 1] = padNum;
661	
662	    auto padArray = executor->AllocIntArray(padVec.data(), padVec.size());
663	    if (padArray == nullptr) {
664	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "Try alloc padVec failed");
665	        return nullptr;
666	    }
667	
668	    auto padTensor = executor->ConvertToTensor(padArray, DataType::DT_INT64);
669	    return padTensor;
670	}
