672	static aclnnStatus Contiguous(const aclTensor *&query,
673	                              const aclTensor *&key,
674	                              const aclTensor *&value,
675	                              const aclTensor *&realShiftOptional,
676	                              const aclTensor *&dropMaskOptional,
677	                              const aclTensor *&paddingMaskOptional,
678	                              const aclTensor *&attenMaskOptional,
679	                              const aclTensor *&queryRope,
680	                              const aclTensor *&keyRope,
681	                              const aclTensor *&sinkOptional,
682	                              const aclTensor *&dScaleQOptional,
683	                              const aclTensor *&dScaleKOptional,
684	                              const aclTensor *&dScaleVOptional,
685	                              aclOpExecutor *executor)
686	{
687	    query = l0op::Contiguous(query, executor);
688	    CHECK_RET(query != nullptr, ACLNN_ERR_PARAM_NULLPTR);
689	    key = l0op::Contiguous(key, executor);
690	    CHECK_RET(key != nullptr, ACLNN_ERR_PARAM_NULLPTR);
691	    value = l0op::Contiguous(value, executor);
692	    CHECK_RET(value != nullptr, ACLNN_ERR_PARAM_NULLPTR);
693	    if (realShiftOptional) {
694	        realShiftOptional = l0op::Contiguous(realShiftOptional, executor);
695	        CHECK_RET(realShiftOptional != nullptr, ACLNN_ERR_PARAM_NULLPTR);
696	    }
697	    if (dropMaskOptional) {
698	        dropMaskOptional = l0op::Contiguous(dropMaskOptional, executor);
699	        CHECK_RET(dropMaskOptional != nullptr, ACLNN_ERR_PARAM_NULLPTR);
700	    }
701	    if (paddingMaskOptional) {
702	        paddingMaskOptional = l0op::Contiguous(paddingMaskOptional, executor);
703	        CHECK_RET(paddingMaskOptional != nullptr, ACLNN_ERR_PARAM_NULLPTR);
704	    }
705	    if (attenMaskOptional) {
706	        attenMaskOptional = l0op::Contiguous(attenMaskOptional, executor);
707	        CHECK_RET(attenMaskOptional != nullptr, ACLNN_ERR_PARAM_NULLPTR);
708	    }
709	    if (queryRope != nullptr) {
710	        queryRope = l0op::Contiguous(queryRope, executor);
711	        CHECK_RET(queryRope != nullptr, ACLNN_ERR_PARAM_NULLPTR);
712	    }
713	    if (keyRope != nullptr) {
714	        keyRope = l0op::Contiguous(keyRope, executor);
715	        CHECK_RET(keyRope != nullptr, ACLNN_ERR_PARAM_NULLPTR);
716	    }
717	    if (sinkOptional != nullptr) {
718	        sinkOptional = l0op::Contiguous(sinkOptional, executor);
719	        CHECK_RET(sinkOptional != nullptr, ACLNN_ERR_PARAM_NULLPTR);
720	    }
721	    if (dScaleQOptional) {
722	        dScaleQOptional = l0op::Contiguous(dScaleQOptional, executor);
723	        CHECK_RET(dScaleQOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
724	    }
725	    if (dScaleKOptional) {
726	        dScaleKOptional = l0op::Contiguous(dScaleKOptional, executor);
727	        CHECK_RET(dScaleKOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
728	    }
729	    if (dScaleVOptional) {
730	        dScaleVOptional = l0op::Contiguous(dScaleVOptional, executor);
731	        CHECK_RET(dScaleVOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
732	    }
733	    return ACLNN_SUCCESS;
734	}
