736	static aclnnStatus PreprocessQKV(const aclTensor *&query,
737	                                 const aclTensor *&key,
738	                                 const aclTensor *&value,
739	                                 const struct FaShapeInfo &shapeInfo,
740	                                 aclOpExecutor *executor)
741	{
742	    if (!StrideLimited()) {
743	        return ACLNN_SUCCESS;
744	    }
745	    if (shapeInfo.needReshape) {
746	        query = l0op::Reshape(
747	            query,
748	            executor->AllocIntArray(shapeInfo.reshapedQueryShape.data(), shapeInfo.reshapedQueryShape.size()),
749	            executor);
750	        CHECK_RET(query != nullptr, ACLNN_ERR_PARAM_NULLPTR);
751	        key =
752	            l0op::Reshape(key,
753	                          executor->AllocIntArray(shapeInfo.reshapedKeyShape.data(), shapeInfo.reshapedKeyShape.size()),
754	                          executor);
755	        CHECK_RET(key != nullptr, ACLNN_ERR_PARAM_NULLPTR);
756	        value = l0op::Reshape(
757	            value,
758	            executor->AllocIntArray(shapeInfo.reshapedValueBefore.data(), shapeInfo.reshapedValueBefore.size()),
759	            executor);
760	        CHECK_RET(value != nullptr, ACLNN_ERR_PARAM_NULLPTR);
761	    }
762	
763	    if (shapeInfo.needPad) {
764	        int32_t dimNum = shapeInfo.inputLayout == InputLayout::TND ? DIM_NUM_3 : DIM_NUM_4;
765	        auto qkPaddings = GeneratePaddings(dimNum, shapeInfo.padNum, executor);
766	        auto vPaddings = GeneratePaddings(dimNum, shapeInfo.padNumv, executor);
767	        if (shapeInfo.padNum != 0) {
768	            query = l0op::Pad(query, qkPaddings, executor);
769	            CHECK_RET(query != nullptr, ACLNN_ERR_PARAM_NULLPTR);
770	            key = l0op::Pad(key, qkPaddings, executor);
771	            CHECK_RET(key != nullptr, ACLNN_ERR_PARAM_NULLPTR);
772	        }
773	        if (shapeInfo.padNumv != 0) {
774	            value = l0op::Pad(value, vPaddings, executor);
775	            CHECK_RET(value != nullptr, ACLNN_ERR_PARAM_NULLPTR);
776	        }
777	    }
778	    if (shapeInfo.needTranspose) {
779	        // B,S,N,D -> B,N,S,D
780	        // S,B,N,D -> B,N,S,D
781	        auto perm = executor->AllocIntArray(shapeInfo.perm_in.data(), shapeInfo.perm_in.size());
782	        query = l0op::Transpose(query, perm, executor);
783	        CHECK_RET(query != nullptr, ACLNN_ERR_PARAM_NULLPTR);
784	        key = l0op::Transpose(key, perm, executor);
785	        CHECK_RET(key != nullptr, ACLNN_ERR_PARAM_NULLPTR);
786	        value = l0op::Transpose(value, perm, executor);
787	        CHECK_RET(value != nullptr, ACLNN_ERR_PARAM_NULLPTR);
788	    }
789	
790	    if (shapeInfo.inputLayout == InputLayout::SBH && shapeInfo.needPad && !shapeInfo.needTranspose) {
791	        // (S,B,N,D) -> (S,B,N*D)
792	        FVector<int64_t, DIM_NUM_3> queryShape{shapeInfo.axes.s1,
793	                                               shapeInfo.axes.b,
794	                                               shapeInfo.axes.n1 *
795	                                                   (shapeInfo.axes.d + static_cast<int64_t>(shapeInfo.padNum))};
796	        FVector<int64_t, DIM_NUM_3> keyShape{shapeInfo.axes.s2,
797	                                             shapeInfo.axes.b,
798	                                             shapeInfo.axes.n2 *
799	                                                 (shapeInfo.axes.d + static_cast<int64_t>(shapeInfo.padNum))};
800	        FVector<int64_t, DIM_NUM_3> ValueShape{shapeInfo.axes.s2,
801	                                               shapeInfo.axes.b,
802	                                               shapeInfo.axes.n2 *
803	                                                   (shapeInfo.axes.dv + static_cast<int64_t>(shapeInfo.padNumv))};
804	
805	        query = l0op::Reshape(query, executor->AllocIntArray(queryShape.data(), queryShape.size()), executor);
806	        CHECK_RET(query != nullptr, ACLNN_ERR_PARAM_NULLPTR);
807	        key = l0op::Reshape(key, executor->AllocIntArray(keyShape.data(), keyShape.size()), executor);
808	        CHECK_RET(key != nullptr, ACLNN_ERR_PARAM_NULLPTR);
809	        value = l0op::Reshape(value, executor->AllocIntArray(ValueShape.data(), ValueShape.size()), executor);
810	        CHECK_RET(value != nullptr, ACLNN_ERR_PARAM_NULLPTR);
811	    }
812	    return ACLNN_SUCCESS;
813	}
