815	static aclnnStatus Postprocess(const aclTensor *&l0AttentionOutOut,
816	                               const aclTensor *attentionOutOut,
817	                               struct FaShapeInfo &shapeInfo,
818	                               aclOpExecutor *executor)
819	{
820	    if (!StrideLimited()) {
821	        return ACLNN_SUCCESS;
822	    }
823	    if (shapeInfo.inputLayout == InputLayout::SBH && shapeInfo.needPad && !shapeInfo.needTranspose) {
824	        // (S,B,Hp) -> (S,B,N,Dp)
825	        FVector<int64_t, DIM_NUM_4> paddedSBNDShape{shapeInfo.axes.s1,
826	                                                    shapeInfo.axes.b,
827	                                                    shapeInfo.axes.n1,
828	                                                    shapeInfo.axes.dv + static_cast<int64_t>(shapeInfo.padNumv)};
829	        l0AttentionOutOut = l0op::Reshape(
830	            l0AttentionOutOut, executor->AllocIntArray(paddedSBNDShape.data(), paddedSBNDShape.size()), executor);
831	        CHECK_RET(l0AttentionOutOut != nullptr, ACLNN_ERR_PARAM_NULLPTR);
832	    }
833	
834	    if (shapeInfo.needTranspose) {
835	        auto perm = executor->AllocIntArray(shapeInfo.perm_out.data(), shapeInfo.perm_out.size());
836	        l0AttentionOutOut = l0op::Transpose(l0AttentionOutOut, perm, executor);
837	        CHECK_RET(l0AttentionOutOut != nullptr, ACLNN_ERR_PARAM_NULLPTR);
838	    }
839	
840	    if (shapeInfo.needPad && shapeInfo.padNumv != 0) {
841	        // (B,S,N,D)
842	        // (S,B,N,D)
843	        // (B,N,S,D)
844	        // (T,N,D)
845	        FVector<int64_t, MAX_DIM_NUM> sizeVec = ToShapeVector(l0AttentionOutOut->GetViewShape());
846	        sizeVec.back() -= shapeInfo.padNumv;
847	        if (shapeInfo.inputLayout == InputLayout::TND) {
848	            FVector<int64_t, DIM_NUM_3> offsetVec(DIM_NUM_3, 0);
849	            l0AttentionOutOut = l0op::Slice(l0AttentionOutOut,
850	                                            executor->AllocIntArray(offsetVec.data(), offsetVec.size()),
851	                                            executor->AllocIntArray(sizeVec.data(), sizeVec.size()),
852	                                            executor);
853	        } else {
854	            FVector<int64_t, DIM_NUM_4> offsetVec(DIM_NUM_4, 0);
855	            l0AttentionOutOut = l0op::Slice(l0AttentionOutOut,
856	                                            executor->AllocIntArray(offsetVec.data(), offsetVec.size()),
857	                                            executor->AllocIntArray(sizeVec.data(), sizeVec.size()),
858	                                            executor);
859	        }
860	        CHECK_RET(l0AttentionOutOut != nullptr, ACLNN_ERR_PARAM_NULLPTR);
861	    }
862	
863	    if (shapeInfo.needReshape) {
864	        auto attentionOutOutShape = ToShapeVector(attentionOutOut->GetViewShape());
865	        l0AttentionOutOut =
866	            l0op::Reshape(l0AttentionOutOut,
867	                          executor->AllocIntArray(attentionOutOutShape.data(), attentionOutOutShape.size()),
868	                          executor);
869	        CHECK_RET(l0AttentionOutOut != nullptr, ACLNN_ERR_PARAM_NULLPTR);
870	    }
871	    return ACLNN_SUCCESS;
872	}
