897	static aclnnStatus isSupportMultiInput(const aclTensor *query,
898	                                       const aclTensor *queryRope,
899	                                       const aclTensor *key,
900	                                       const aclTensor *keyRope,
901	                                       const aclTensor *value,
902	                                       const aclTensor *attenMaskOptional,
903	                                       const aclTensor *pseShiftOptional,
904	                                       const aclTensor *dropMaskOptional,
905	                                       double keepProb,
906	                                       const FaShapeInfo &faShape,
907	                                       int64_t sparseMode)
908	{
909	    CHECK_RET((queryRope == nullptr && keyRope == nullptr) || (queryRope != nullptr && keyRope != nullptr),
910	              ACLNN_ERR_PARAM_NULLPTR);
911	    auto vDtype = value->GetDataType();
912	    auto kDtype = key->GetDataType();
913	    auto qDtype = query->GetDataType();
914	    if (queryRope != nullptr && keyRope != nullptr) {
915	        auto kRopeDtype = keyRope->GetDataType();
916	        auto qRopeDtype = queryRope->GetDataType();
917	        Shape qRopeShape = queryRope->GetViewShape();
918	        Shape kRopeShape = keyRope->GetViewShape();
919	        if (qRopeShape[DIM_NUM_2] > faShape.axes.d || kRopeShape[DIM_NUM_2] > faShape.axes.d) {
920	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
921	                    "Invalid input, do not support query_rope and key_rope when"
922	                    " the head-dim of query_rope or key_rope is larger than the head-dim of query.");
923	            return ACLNN_ERR_PARAM_INVALID;
924	        }
925	        if (qDtype != ge::DataType::DT_BF16 || kDtype != ge::DataType::DT_BF16 || vDtype != ge::DataType::DT_BF16 ||
926	            qRopeDtype != ge::DataType::DT_BF16 || kRopeDtype != ge::DataType::DT_BF16) {
927	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
928	                    "The data type of query[%s], queryRope[%s], key[%s], keyRope[%s], value[%s]"
929	                    " should be BFloat16.",
930	                    op::ToString(DataType(qDtype)).GetString(),
931	                    op::ToString(DataType(qRopeDtype)).GetString(),
932	                    op::ToString(DataType(kDtype)).GetString(),
933	                    op::ToString(DataType(kRopeDtype)).GetString(),
934	                    op::ToString(DataType(vDtype)).GetString());
935	            return ACLNN_ERR_PARAM_INVALID;
936	        }
937	        if (sparseMode == 6) {
938	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
939	                    "Invalid input, do not support query_rope and key_rope when sparseMode is 6.");
940	            return ACLNN_ERR_PARAM_INVALID;
941	        }
942	
943	        if (attenMaskOptional == nullptr || attenMaskOptional->GetViewShape().GetDimNum() == 0) {
944	            OP_LOGE(ACLNN_ERR_PARAM_NULLPTR,
945	                    "Invalid input, only support query_rope and key_rope when attentionMask is given.");
946	            return ACLNN_ERR_PARAM_NULLPTR;
947	        }
948	        if (pseShiftOptional != nullptr) {
949	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
950	                    "Invalid input, only support query_rope and key_rope when pseShift is nullptr.");
951	            return ACLNN_ERR_PARAM_INVALID;
952	        }
953	        if (dropMaskOptional != nullptr) {
954	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
955	                    "Invalid input, only support query_rope and key_rope when dropMask is nullptr.");
956	            return ACLNN_ERR_PARAM_INVALID;
957	        }
958	        if (keepProb < 1.0F) {
959	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Invalid input, only support query_rope and key_rope when keepProb = 1.");
960	            return ACLNN_ERR_PARAM_INVALID;
961	        }
962	        if (faShape.inputLayout != InputLayout::TND) {
963	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
964	                    "Invalid input, only support query_rope and key_rope as input for layout TND.");
965	            return ACLNN_ERR_PARAM_INVALID;
966	        }
967	
968	        if (faShape.needPad || faShape.needTranspose || faShape.needReshape || faShape.needPadValue) {
969	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
970	                    "Invalid input, do not support query_rope and key_rope as input when shape is not aligned with 128 "
971	                    "or other corner cases.");
972	            return ACLNN_ERR_PARAM_INVALID;
973	        }
974	    }
975	    return ACLNN_SUCCESS;
976	}
