591	template <typename T>
592	int CreateAclTensor(const std::vector<T>& hostData, const std::vector<int64_t>& shape, void** deviceAddr,
593	                    aclDataType dataType, aclTensor** tensor) {
594	  auto size = GetShapeSize(shape) * sizeof(T);
595	  // 调用aclrtMalloc申请device侧内存
596	  auto ret = aclrtMalloc(deviceAddr, size, ACL_MEM_MALLOC_HUGE_FIRST);
597	  CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclrtMalloc failed. ERROR: %d\n", ret); return ret);
598	  // 调用aclrtMemcpy将host侧数据拷贝到device侧内存上
599	  ret = aclrtMemcpy(*deviceAddr, size, hostData.data(), size, ACL_MEMCPY_HOST_TO_DEVICE);
600	  CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclrtMemcpy failed. ERROR: %d\n", ret); return ret);
601	
602	  // 计算连续tensor的strides
603	  std::vector<int64_t> strides(shape.size(), 1);
604	  for (int64_t i = shape.size() - 2; i >= 0; i--) {
605	    strides[i] = shape[i + 1] * strides[i + 1];
606	  }
607	
608	  // 调用aclCreateTensor接口创建aclTensor
609	  *tensor = aclCreateTensor(shape.data(), shape.size(), dataType, strides.data(), 0, aclFormat::ACL_FORMAT_ND,
610	                            shape.data(), shape.size(), *deviceAddr);
611	  return 0;
612	}
