    softmax_layout_char[LAYOUT_MAX_LENGTH - 1] = '\0';

    EXEC_NPU_CMD_V1(aclnnFlashAttentionVarLenScoreEnhanceV5,
                    query,
                    query_rope,
                    key,
                    key_rope,
                    value,
                    pse,
                    drop_mask,
                    padding_mask,
                    atten_mask,
                    sink,
                    prefixN,
                    ac_seq_qlen,
                    ac_seq_kvlen,
                    q_start_index,
                    kv_start_index,
