                    keep_prob,
                    pre_tokens,
                    next_tokens,
                    head_num,
                    input_layout_str,
                    inner_precise,
                    sparse_mode,
                    pse_type,
                    softmax_layout_char,
                    sink_num,
                    softmax_max,
                    softmax_sum,
                    softmax_out,
                    attention_score);
    return std::make_tuple(std::move(attention_score), std::move(softmax_max), std::move(softmax_sum));
